CREATE TRIGGER json_sources_settings_insert BEFORE INSERT ON sources
WHEN NEW.settings IS NOT NULL AND CASE WHEN NOT json_valid(NEW.settings) THEN 1 WHEN json_type(NEW.settings)<>'object' THEN 1 ELSE (
EXISTS(SELECT 1 FROM json_tree(NEW.settings) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
) END BEGIN SELECT RAISE(ABORT,'JSON contract violation: sources.settings'); END;
